def dropout_forward(h, p, training):
    # p: 뉴런 제거 확률 (역드롭아웃 방식)
    if not training:
        return h  # 추론: 전체 뉴런 그대로 사용
    scale = 1.0 / (1.0 - p)  # 출력 기대값 유지
    out = []
    for x in h:
        if random() < p:
            out.append(0.0)  # 비활성화
        else:
            out.append(x * scale)
    return out
